"Quick match against a real player.":"Gerçek bir oyuncuya karşı hızlı maç.",
"Quick match against real players.":"Gerçek oyunculara karşı hızlı maç.",
"The first online one":"İlk online oyun",
"Memory, head to head":"Hafıza, kafa kafaya",
"Two card games":"İki kart oyunu",
"On the roofs at sunset":"Gün batımında çatılarda",
"the same song and the same shots at the same time, side by side - the highest score wins.":"aynı şarkı ve aynı atışlar, aynı anda, yan yana - en yüksek skor kazanır.",
"take turns - make a shot and they have to make it too, or it's a letter. Spell HORSE and you're out. A win is +25 points.":"sırayla - sen bir atış sokarsın, o da sokmak zorunda, yoksa bir harf alır. HORSE tamamlanırsa oyun biter. Galibiyet +25 puan.",
"one bed of cards between you - take turns turning two, a pair and you go again, the most pairs wins.":"aranızda tek bir kart yatağı - sırayla ikişer kart çevirin, çift bulursan yine sen oynarsın, en çok çifti bulan kazanır.",
"the same cards for both at the same time - the quicker snap takes the pair. A win is +25 points.":"ikiniz için aynı kartlar, aynı anda - en hızlı snap çifti alır. Galibiyet +25 puan.",
"for 2, 3 or 4: the same nine holes at the same time, the others as ghost balls - the fewest strokes takes the hole, the most holes wins.":"2, 3 ya da 4 kişilik: aynı dokuz delik aynı anda, diğerleri hayalet top olarak - en az vuruş deliği alır, en çok deliği alan kazanır.",
"one air hockey table, first to 3 rounds. A win is +25 points; with 3 or 4, 2nd place earns some too.":"tek bir hava hokeyi masası, 3 raundu ilk alan kazanır. Galibiyet +25 puan; 3 ya da 4 kişiyle 2. sıra da biraz kazanır.",
"Quick match against a real player, one pattern of lights between you. Play it back, add a light of your own, pass it on - and remember every one they add. Get one wrong and it's a Z; three Z's and you fell asleep. A win is +25 points.":"Gerçek bir oyuncuya karşı hızlı maç, aranızda tek bir ışık dizisi. Tekrar çal, kendi ışığını ekle, sırayı devret - ve onun eklediği her ışığı hatırla. Birini yanlış yaparsan bir Z alırsın; üç Z ve uyuyakaldın. Galibiyet +25 puan.",
