"Your JAVEDA player is deleted. Your Lightning Wolves login stays, because you also use it for the Studio or the Wolf Hub.":"JAVEDA oyuncun silindi. Lightning Wolves girişin duruyor, çünkü onu Studio ya da Wolf Hub için de kullanıyorsun.",
