"# runs you played offline are on your account now":"Çevrimdışı oynadığın # oyun artık hesabında",
"You're offline: endless scores only count with internet.":"Çevrimdışısın: Sonsuz skorları sadece internetle sayılır.",
"You're offline: the daily challenge only counts with internet.":"Çevrimdışısın: günlük meydan okuma sadece internetle sayılır.",
"You're offline. Log-in needs the internet the first time.":"Çevrimdışısın. İlk giriş için internet gerekir.",
"This song isn't saved on this phone yet. Play it once with internet, or save all the songs in the app.":"Bu şarkı henüz bu telefona kaydedilmedi. Bir kez internetle oyna ya da uygulamada tüm şarkıları kaydet.",
"Want your name up here?":"Adın burada olsun mu?",
"Playing as a guest, your progress stays on this phone only.":"Misafir olarak oynadığın için ilerlemen sadece bu telefonda kalır.",
