"The scoreboard is for players with an account. It's free: your scores go on the board, you earn points, and your progress is saved on every phone and computer.":"Skor tablosu hesabı olan oyuncular için. Ücretsiz: skorların tabloya girer, puan kazanırsın ve ilerlemen her telefonda ve bilgisayarda kayıtlı kalır.",
"Show the top #":"En iyi # kişiyi göster",
"I finished JAVEDA - all # songs of Lazy Jo's playable album.":"JAVEDA tamam! Lazy Jo imzalı oynanabilir albümdeki # şarkının hepsini bitirdim.",
