"In the list, pick Instagram, then Story. The link is copied: add a Link sticker and paste it.":"Listeden Instagram'ı, sonra Hikâye'yi seç. Bağlantı kopyalandı: bir Bağlantı çıkartması ekle ve yapıştır.",
"In the list, pick TikTok. The link is copied: paste it in your caption.":"Listeden TikTok'u seç. Bağlantı kopyalandı: açıklamana yapıştır.",
"Picture saved and link copied. Post the picture from your phone and paste the link.":"Resim kaydedildi, bağlantı kopyalandı. Resmi telefonundan paylaş ve bağlantıyı yapıştır.",
"Share the picture":"Resmi paylaş",
"Send the link - it shows the JAVEDA preview in the chat. Or put the picture in your story.":"Bağlantıyı gönder - sohbette JAVEDA önizlemesi görünür. Ya da resmi hikâyene koy.",
"Save the picture and post it to your story. The link to play is on it.":"Resmi kaydet ve hikâyende paylaş. Oynama bağlantısı üstünde.",
"I finished JAVEDA - all 28 songs of Lazy Jo's playable album.":"JAVEDA tamam! Lazy Jo imzalı oynanabilir albümdeki 28 şarkının hepsini bitirdim.",
