"to get on the daily board.":"ve günlük tabloya gir.",
"⚡ JAVEDA Pass":"⚡ JAVEDA Pass",
"Get the Pass":"Pass'i al",
"See it free":"Ücretsiz göz at",
"The whole album, right now":"Albümün tamamı, hemen şimdi",
"Every part of all 28 songs, open right away":"28 şarkının tüm bölümleri, anında açık",
"Every endless and remix, and a place on their scoreboards":"Tüm Sonsuz ve Remix modları, skor tablolarında da yerin",
"One payment, no subscription. Yours for good.":"Tek ödeme, abonelik yok. Sonsuza dek senin.",
"The whole game stays free if you play for it: finish a part and the next one opens. The Pass is for when you don't want to wait.":"Oynayarak açarsan oyunun tamamı ücretsiz kalır: bir bölümü bitir, sıradaki açılsın. Pass, beklemek istemediğin zamanlar için.",
"A code from EVEN or your merch":"EVEN'dan ya da merch'ünden bir kod",
"No code?":"Kodun yok mu?",
"Redeem":"Kullan",
"Unlock with the JAVEDA Pass":"JAVEDA Pass ile aç",
"Log in first: the Pass goes on your account.":"Önce giriş yap: Pass hesabına tanımlanır.",
"No payment made. The Pass is here whenever you want it.":"Ödeme yapılmadı. Pass, ne zaman istersen burada.",
"Log in with the account you paid with: the Pass is on it.":"Ödeme yaptığın hesapla giriş yap: Pass o hesapta.",
"Your payment is going through. The Pass shows up as soon as it's done: refresh in a minute.":"Ödemen işleniyor. Biter bitmez Pass görünür: bir dakika sonra sayfayı yenile.",
"🎧 Spotify":"🎧 Spotify",
"👕 Merch":"👕 Merch",
