"The saucer skims the sea toward the sun. Jump the big waves, keep off the rocks, grab the lights.":"Uçan daire güneşe doğru denizin üstünde kayıyor. Büyük dalgaların üstünden zıpla, kayalardan uzak dur, ışıkları topla.",
