"From the Earth in your hands to Planet Javeda, in the little orange ship. Every planet on the way is under a meteor shower.":"Avuçlarındaki Dünya'dan Javeda Gezegeni'ne, küçük turuncu gemiyle. Yoldaki her gezegene meteor yağıyor.",
"The long way home: the meteors hunt you in flight too, and you start with # hearts.":"Eve dönüş uzun: meteorlar uçarken de peşinde ve oyuna # kalple başlıyorsun.",
"PETAL RAIN":"YAPRAK YAĞMURU",
"The rose in the canyon is losing its petals. Catch them in the saucer's green beam before they hit the cracked ground.":"Kanyondaki gül yapraklarını döküyor. Çatlak toprağa düşmeden onları uçan dairenin yeşil ışınıyla yakala.",
"ROSE # / #":"GÜL # / #",
"THE ROSE LOST ALL ITS PETALS":"GÜL TÜM YAPRAKLARINI KAYBETTİ",
"Climb the giant stem all the way to the bloom - round the thorns, through the dew.":"Dev sapı ta çiçeğe kadar tırman - dikenlerin etrafından, çiy damlalarının arasından.",
"THROUGH THE GAP":"ARALIKTAN GEÇ",
"# M · # IN A ROW":"# M · # SERİ",
"SHADOW # S BEHIND":"GÖLGE # SN GERİDE",
"YOUR SHADOW GOT YOU":"GÖLGEN SENİ YAKALADI",
"THE KING OF FORGETTING":"UNUTUŞ KRALI",
"LAZY JO × ZIRKA · LEVEL #":"LAZY JO × ZIRKA · SEVİYE #",
"NIGHT FLIGHT":"GECE UÇUŞU",
"District #, the night the monsters of forgetting came. Fly Jo's saucer between the neon towers and light them up.":"District #, unutuş canavarlarının geldiği gece. Jo'nun uçan dairesini neon kuleler arasında uçur ve hepsini aydınlat.",
"# DOWN":"# VURULDU",
"STORM #s":"FIRTINA # SN",
"THE SWARM!":"SÜRÜ GELİYOR!",
"LAZY JO × ZIRKA · LEVEL # PART #":"LAZY JO × ZIRKA · SEVİYE # BÖLÜM #",
"Zirka's bike over the rooftops of District # - jump the gaps on the beat, and Zirka's gun takes care of what dives in.":"Zirka'nın motoru District # çatılarında - boşlukların üstünden ritimde zıpla, dalışa geçenleri Zirka'nın silahı halleder.",
"# BOLTS · # DOWN":"# ŞİMŞEK · # VURULDU",
"x# · # BOLTS · # DOWN":"x# · # ŞİMŞEK · # VURULDU",
"The King of Forgetting hangs over the city. Bring him down before the song ends. Gadgets float up for Jo - and the wolf token hands the fight to Zirka on the roof below.":"Unutuş Kralı şehrin üstünde asılı duruyor. Şarkı bitmeden onu indir. Jo için yukarı aletler süzülüyor - kurt jetonu da savaşı aşağıdaki çatıda Zirka'ya devrediyor.",
"x# · # CORE HITS":"x# · # ÇEKİRDEK İSABETİ",
"# CORE HITS":"# ÇEKİRDEK İSABETİ",
"Jo's orange saucer drops into the city from the sky. Freefall down between the towers - through the skybridges, past the cranes and the helicopters - all the way to the streets.":"Jo'nun turuncu uçan dairesi gökten şehre düşüyor. Kulelerin arasından serbest düşüşe geç - geçit köprülerinin içinden, vinçlerin ve helikopterlerin yanından - ta sokaklara kadar.",
"# M DOWN":"# M AŞAĞIDA",
"A CRANE!":"VİNÇ!",
"A night race through the city, towards the moon, in Jo's silver car - its tail lights drawing a trail of light behind it. Seven cars start ahead of you: drift round the corners, hit the nitro on the beat and be first to the river.":"Şehirde, aya doğru bir gece yarışı, Jo'nun gümüş arabasıyla - arka lambaları ardında ışıktan bir iz bırakıyor. Yedi araba senden önde başlıyor: virajlarda drift at, ritimde nitroya bas ve nehre ilk sen var.",
"P# · # KM/H":"P# · # KM/SA",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out.":"Sahnedeki hologram saat mekanizmasının içinden geç. Jo'nun uçan dairesi ışınını sarkaçlara takıyor - sallan, bırak, uç, sonrakine takıl. Şarkı bitmeden sonuna kadar git.",
"# M · # ON THE BEAT":"# M · # RİTİMDE",
"YOU FELL":"DÜŞTÜN",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room.":"Kapaktaki oda, yukarıdan. Jo'nun uçan dairesi hiç durmaz - gittiği her yerde halıya ışıktan bir iz çizer. Odadaki en uzun ışık seninki olsun.",
"TRAIL # M":"İZ # M",
"CROSSED!":"İZİNİ KESTİN!",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you.":"Kapaktaki neon bardağın içindesin. Uçan daire raket, mor bir damla da top - buz sana inmeden buz küplerini ve pembe sıçrantıyı kır.",
"# BROKEN · # LEFT":"# KIRILDI · # KALDI",
"# BROKEN · # LEFT · # IN A ROW":"# KIRILDI · # KALDI · # SERİ",
"THE ICE COMES DOWN":"BUZ İNİYOR",
"MISSED IT":"KAÇIRDIN",
"The old houses on the street from the cover, at dusk, in the fog. Ghosts come up in the windows on the beat - catch them with the saucer's beam before they duck away.":"Kapaktaki sokağın eski evleri, alacakaranlıkta, siste. Hayaletler ritimde pencerelerde beliriyor - saklanmadan onları uçan dairenin ışınıyla yakala.",
"# CAUGHT · HAUNTED #/#":"# YAKALANDI · PERİLİ #/#",
"HAUNTED":"PERİLİ",
"LAZY JO FEAT. ZIRKA · LEVEL #":"LAZY JO FEAT. ZIRKA · SEVİYE #",
"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish.":"Kapaktaki beyaz gökyüzünde süzülen mor-altın bir saha, Zirka'nın uçan dairesi de potanın yanında. Güç toplamak için basılı tut, yeşilde bırak - ritimde atarsan swish.",
"Warm up on your own":"Tek başına ısın",
"#/# IN · # SWISH":"#/# İSABET · # SWISH",
"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold.":"Kapaktaki mavi gökyüzü ve adalar. Denizde altın bir çerçeve duruyor; Jo'nun uçan dairesi parçaları ışınıyla aşağı indiriyor - ada parçaları, altın, gök, bulut. Bir sırayı doldur, altın gibi patlasın.",
"# ROWS":"# SIRA",
"LAZY JO FT ZIRKA · LEVEL #":"LAZY JO FT ZIRKA · SEVİYE #",
"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out.":"Kapaktaki ıslak sokakta bir otopark, gece, yağmur altında. Mavi araba sıkışmış - diğerlerini yolundan kaydır ki çıkabilsin.",
"Part # · Unblock":"Bölüm # · Unblock",
"Part # · Light Link":"Bölüm # · Light Link",
"CAR PARK # · # OUT · # BARS":"OTOPARK # · # ÇIKTI · # ÖLÇÜ",
"LAZY JO FT ZIRKA · LEVEL # · PART #":"LAZY JO FT ZIRKA · SEVİYE # · BÖLÜM #",
"The wet street from the cover at night, in the rain. The saucer's beam goes flat across it - bend it with the mirrors so it reaches the car's headlights.":"Kapaktaki ıslak sokak, gece, yağmur altında. Uçan dairenin ışını sokağı yatay kesiyor - aynalarla bükerek arabanın farlarına ulaştır.",
"STREET # · # LIT · # BARS":"SOKAK # · # YANDI · # ÖLÇÜ",
"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them.":"Kapaktaki gibi gece vakti Jo'nun stüdyosu - büyük hoparlörler, kalabalığı gösteren ekran, masadaki kafatası. Masada ritim makinesi: alttan ışıklı # pad, her birinin kendi notası, Jo'nun uçan dairesi de üstlerinde süzülüyor.",
"YOUR TURN · # / #":"SIRA SENDE · # / #",
"STAY UP #":"STAY UP #",
"The crowd from the cover under the blue light, every hand up, the big white light behind - and nine lights over them, each its own note. Jo's saucer hovers by the one you play.":"Kapaktaki kalabalık mavi ışığın altında, bütün eller havada, arkada büyük beyaz ışık - üstlerinde de dokuz ışık, her birinin kendi notası. Jo'nun uçan dairesi çaldığın ışığın yanında süzülüyor.",
