"The winner gets a discount code for Lazy Jo's merch shop; the top three each get a key to open a song.":"Kazanan Lazy Jo'nun mağazası için indirim kodu alır; ilk üç oyuncunun her biri bir şarkıyı açan bir anahtar kazanır.",
