"Lap <b>#</b> · # games · <b>#</b> without stopping · # down · # king fallen":"Tur <b>#</b> · # oyun · durmadan <b>#</b> · # indirildi · # kral düştü",
"Lap <b>#</b> · # games · <b>#</b> without stopping · # down · # kings fallen":"Tur <b>#</b> · # oyun · durmadan <b>#</b> · # indirildi · # kral düştü",
"Every part's rules in turn, one score, # hearts. Your best goes on the <b>Level # Remix</b> scoreboard.":"Her bölümün kuralları sırayla, tek skor, # kalp. Rekorun <b>Seviye # Remix</b> skor tablosuna girer.",
